parameters.jsCode:
const body = $input.first().json.body || $input.first().json;

if (!body.prompt || typeof body.prompt !== 'string' || body.prompt.trim() === '') {
  throw new Error('Missing required parameter: "prompt" must be a non-empty string.');
}

// Resolve Colab worker URL
const colabUrl = (body.colab_url || $env.WAN2_COLAB_URL || '').replace(/\/+$/, '');
if (!colabUrl) {
  throw new Error('Colab worker URL is not configured. Pass "colab_url" in request body or set WAN2_COLAB_URL in n8n environment variables.');
}

const cameraMotion = body.camera_motion || body.camera || 'orbit_360';
const resolution = body.resolution || '832x480';
const frameCount = parseInt(body.frame_count || body.frames || 81, 10);
const fps = parseInt(body.fps || 30, 10);
const outputDir = body.output_dir || body.outputDir || './public/frames';
if (!/^[a-zA-Z0-9_\-\/\.]+$/.test(outputDir)) {
  throw new Error('Invalid output_dir. Only alphanumeric characters, dashes, underscores, dots, and slashes are allowed.');
}
const seed = body.seed !== undefined ? parseInt(body.seed, 10) : -1;
const guidanceScale = parseFloat(body.guidance_scale || 5.0);
const numInferenceSteps = parseInt(body.steps || body.num_inference_steps || 35, 10);

return [{
  json: {
    prompt: body.prompt.trim(),
    camera_motion: cameraMotion,
    resolution: resolution,
    frame_count: frameCount,
    fps: fps,
    seed: seed,
    guidance_scale: guidanceScale,
    num_inference_steps: numInferenceSteps,
    output_dir: outputDir,
    colab_url: colabUrl,
    timestamp: new Date().toISOString()
  }
}];

