const genRes = $input.first().json;
const prevConfig = $('Validate & Configure Parameters').first().json;

let downloadUrl = genRes.download_url;
if (downloadUrl && downloadUrl.startsWith('/')) {
  downloadUrl = `${prevConfig.colab_url}${downloadUrl}`;
} else if (!downloadUrl && genRes.filename) {
  downloadUrl = `${prevConfig.colab_url}/api/download/${genRes.filename}`;
}

const tempVideoPath = `/tmp/wan2_${genRes.filename || ('video_' + Date.now() + '.mp4')}`;

return [{
  json: {
    ...prevConfig,
    genStatus: genRes.status,
    filename: genRes.filename,
    downloadUrl: downloadUrl,
    tempVideoPath: tempVideoPath,
    genMeta: genRes.metadata || {}
  }
}];

const execOutput = $input.first().json;
const config = $('Prepare Download & Temp Paths').first().json;

let manifestData = {};
try {
  const stdout = execOutput.stdout || '';
  const jsonMatch = stdout.match(/\{[\s\S]*"frameCount"[\s\S]*\}/);
  if (jsonMatch) {
    manifestData = JSON.parse(jsonMatch[0]);
  }
} catch (err) {
  // Fallback
}

return [{
  json: {
    success: true,
    message: "3D camera trajectory frames generated and extracted successfully.",
    prompt: config.prompt,
    cameraMotion: config.camera_motion,
    resolution: config.resolution,
    frameCount: manifestData.frameCount || config.frame_count,
    outputDirectory: config.output_dir,
    manifestPath: `${config.output_dir}/manifest.json`,
    manifest: manifestData,
    pipeline: {
      model: config.genMeta?.model || "Wan-AI/Wan2.1-T2V-1.3B-Diffusers",
      fps: manifestData.fps || config.fps,
      format: manifestData.format || "webp",
      pattern: manifestData.framePattern || "frame_%04d.webp",
      samplePath: `${config.output_dir}/frame_0001.webp`
    },
    completedAt: new Date().toISOString()
  }
}];
